#!/bin/bash
# PatchTST on Traffic: input 96, horizons 96 192 336 720; settings of the official scripts, protocol of the official loaders.
# Generated by scripts/multivariate_forecasting/make_scripts.py: change the profile and generate again.
#   bash scripts/multivariate_forecasting/Traffic/PatchTST.sh                                   seeds 2021 2022 2023
#   SEEDS="2021" EXTRA_ARGS="--no_use_gpu --num_workers 0" bash scripts/multivariate_forecasting/Traffic/PatchTST.sh   one seed on the CPU
# Results: output/long_term_forecast/Traffic.tsv (one row per run); checkpoints: temp/checkpoints/Traffic/.
export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
cd "$(dirname "$0")/../../.."
root="$(python -m src.utils.paths root traffic.csv)/"
seeds=(${SEEDS:-2021 2022 2023})

# horizon 96: scripts/benchmark/official/TSLib/Traffic_script/PatchTST.sh
for seed in "${seeds[@]}"; do
  python -u scripts/run.py \
    --is_training 1 \
    --model PatchTST \
    --des Traffic_96_PatchTST \
    --seed "$seed" \
    --root_path "$root" \
    --data_path traffic.csv \
    --data custom \
    --model_id Traffic_96_96 \
    --features M \
    --seq_len 96 \
    --label_len 48 \
    --pred_len 96 \
    --enc_in 862 \
    --dec_in 862 \
    --c_out 862 \
    --freq h \
    --drop_last \
    --test_batch_size 1 \
    --e_layers 2 \
    --d_layers 1 \
    --factor 3 \
    --d_model 512 \
    --d_ff 512 \
    --top_k 5 \
    --batch_size 4 \
    $EXTRA_ARGS
done

